import { use } from 'react'
import { Box, IconButton, useTheme } from '@mui/material'
import KBTooltipTarget from '@/components/common/tooltip/KBTooltipTarget'
import UserContext from '@/contexts/user/UserContext'

const SIZE = 16
const BUTTON_SIZE = 'small'

const ActionIcon = ({
  asDiv = false,
  color,
  Icon,
  onClick,
  restrictReadOnly = false,
  size = SIZE,
  sx = {},
  tooltip,
  tooltipPlacement = 'top',
  ...props
}) => {
  const theme = useTheme()
  const { isReadOnly } = use(UserContext)

  const isDisabled = restrictReadOnly && isReadOnly

  const hoverColor = color ? theme.palette[color]?.main || theme.palette.primary.main : theme.palette.primary.main

  const sizedIcon = <Icon size={size} />

  if (asDiv) {
    const divElement = (
      <Box
        onClick={isDisabled ? undefined : onClick}
        sx={{
          alignItems: 'center',
          borderRadius: '50%',
          cursor: isDisabled ? 'not-allowed' : 'pointer',
          display: 'flex',
          justifyContent: 'center',
          opacity: isDisabled ? 0.5 : 1,
          padding: '4px',
          '&:hover': {
            ...(isDisabled ? {} : theme.kb?.icon?.hover),
            ...(color && !isDisabled && { color: hoverColor }),
          },
          ...sx,
        }}
        {...props}
      >
        {sizedIcon}
      </Box>
    )

    if (tooltip) {
      return (
        <KBTooltipTarget title={tooltip} placement={tooltipPlacement}>
          {divElement}
        </KBTooltipTarget>
      )
    }

    return divElement
  }

  const button = (
    <IconButton
      size={BUTTON_SIZE}
      disabled={isDisabled}
      onClick={onClick}
      sx={{
        '&:hover': {
          ...(isDisabled ? {} : theme.kb?.icon?.hover),
          ...(color && !isDisabled && { color: hoverColor }),
        },
        ...sx,
      }}
      {...props}
    >
      {sizedIcon}
    </IconButton>
  )

  if (tooltip) {
    return (
      <KBTooltipTarget title={tooltip} placement={tooltipPlacement}>
        {button}
      </KBTooltipTarget>
    )
  }

  return button
}

export default ActionIcon
